    fn slide_u16x8<const SHIFT: usize>(self, a: u16x8<Self>, b: u16x8<Self>) -> u16x8<Self> {
        if SHIFT >= 8usize {
            return b;
        }
        let result = dyn_slide_128(
            Bytes::to_bytes(a).val.0,
            Bytes::to_bytes(b).val.0,
            SHIFT * 2usize,
        );
        Bytes::from_bytes(u8x16 {
            val: crate::support::Aligned128(result),
            simd: self,
        })
    }
