        let sum = u16x8_add(sum, u16x8_shuffle::<2, 3, 4, 5, 6, 7, 0, 1>(sum, sum));
        let sum = u16x8_add(sum, u16x8_shuffle::<1, 2, 3, 4, 5, 6, 7, 0>(sum, sum));
