    fn set_mask16x8(self, a: &mut mask16x8<Self>, index: usize, value: bool) -> () {
        assert!(
            index < 8usize,
            "mask lane index {index} is out of bounds for {} lanes",
            8usize
        );
        let mut lanes: [i16; 8usize] = (*a).into();
        lanes[index] = if value { !0 } else { 0 };
        *a = lanes.simd_into(self);
    }
